    79→
    80→### Pattern 1: Control Panel Wrapper Pattern
    81→
    82→**What:** UI component that wraps AnimationEngine API with HTML controls and keyboard shortcuts
    83→
    84→**When to use:** For all user-facing playback controls (step, play/pause, reset, speed)
    85→
    86→**Example:**
    87→```javascript
    88→// Pattern: Control panel as thin wrapper over AnimationEngine
    89→// Source: HTML5 Media Controls patterns (MDN)
    90→// https://developer.mozilla.org/en-US/docs/Web/API/HTMLMediaElement
    91→
    92→class ControlPanel {
    93→  constructor(engine, containerElement) {
    94→    this.engine = engine;
    95→    this.container = containerElement;
    96→
    97→    this._createControls();
    98→    this._wireKeyboardShortcuts();
    99→    this._updateButtonStates();
   100→
   101→    // Listen to engine state changes to update UI
   102→    window.addEventListener('cpu:framechange', () => this._updateButtonStates());
   103→  }
   104→
   105→  _createControls() {
   106→    this.container.innerHTML = `
   107→      <div class="control-panel">
   108→        <button id="btn-reset" aria-label="Reset to start">
   109→          <span aria-hidden="true">↺</span> Reset
   110→        </button>
   111→        <button id="btn-step-back" aria-label="Step backward">
   112→          <span aria-hidden="true">◀</span> Step Back
   113→        </button>
   114→        <button id="btn-play-pause" aria-label="Play/Pause">
   115→          <span aria-hidden="true">▶</span> Play
   116→        </button>
   117→        <button id="btn-step-forward" aria-label="Step forward">
   118→          Step Forward <span aria-hidden="true">▶</span>
   119→        </button>
   120→
   121→        <label for="speed-select">Speed:</label>
   122→        <select id="speed-select" aria-label="Playback speed">
   123→          <option value="0.25">0.25x (Very Slow)</option>
   124→          <option value="0.5">0.5x (Slow)</option>
   125→          <option value="1" selected>1x (Normal)</option>
   126→          <option value="2">2x (Fast)</option>
   127→          <option value="4">4x (Very Fast)</option>
   128→        </select>
   129→
   130→        <span class="status" aria-live="polite" id="frame-status">
   131→          Frame 0 of 0
   132→        </span>
   133→      </div>
   134→    `;
   135→
   136→    // Wire up events
   137→    this.container.querySelector('#btn-reset').onclick = () => this.engine.reset();
   138→    this.container.querySelector('#btn-step-back').onclick = () => this.engine.stepBackward();
   139→    this.container.querySelector('#btn-play-pause').onclick = () => this.engine.togglePlayPause();
   140→    this.container.querySelector('#btn-step-forward').onclick = () => this.engine.stepForward();
   141→    this.container.querySelector('#speed-select').onchange = (e) => {
   142→      this.engine.setSpeed(parseFloat(e.target.value));
   143→    };
   144→  }
   145→
   146→  _wireKeyboardShortcuts() {
   147→    document.addEventListener('keydown', (e) => {
   148→      // Space: play/pause (like video players)
   149→      if (e.code === 'Space' && e.target === document.body) {
   150→        e.preventDefault();
   151→        this.engine.togglePlayPause();
   152→      }
   153→      // Arrow Left: step back
   154→      else if (e.code === 'ArrowLeft') {
   155→        e.preventDefault();
   156→        this.engine.stepBackward();
   157→      }
   158→      // Arrow Right: step forward
   159→      else if (e.code === 'ArrowRight') {
   160→        e.preventDefault();
   161→        this.engine.stepForward();
   162→      }
   163→      // R: reset
   164→      else if (e.code === 'KeyR') {
   165→        e.preventDefault();
   166→        this.engine.reset();
   167→      }
   168→    });
   169→  }
   170→
   171→  _updateButtonStates() {
   172→    const isPlaying = this.engine.isPlaying;
   173→    const isAtStart = this.engine.isAtStart();
   174→    const isAtEnd = this.engine.isAtEnd();
   175→
   176→    // Update play/pause button
   177→    const playBtn = this.container.querySelector('#btn-play-pause');
   178→    playBtn.innerHTML = isPlaying
   179→      ? '<span aria-hidden="true">⏸</span> Pause'
   180→      : '<span aria-hidden="true">▶</span> Play';
   181→
   182→    // Disable step back at start
   183→    this.container.querySelector('#btn-step-back').disabled = isAtStart;
   184→
   185→    // Disable step forward at end
   186→    this.container.querySelector('#btn-step-forward').disabled = isAtEnd;
   187→
   188→    // Update status text
   189→    const progress = this.engine.getProgress();
   190→    this.container.querySelector('#frame-status').textContent =
   191→      `Frame ${progress.current} of ${progress.total - 1}`;
   192→  }
   193→}
   194→```
   195→
   196→**Why this pattern:**
   197→- Thin wrapper keeps UI code simple - all logic in AnimationEngine
   198→- Keyboard shortcuts follow video player conventions (Space, Arrow keys)
   199→- Button states update automatically via cpu:framechange events
   200→- ARIA labels and live regions for screen reader accessibility
