   202→### Pattern 2: Memory View Component (Hex Table Display)
   203→
   204→**What:** View component displaying data memory addresses and values in hex format
   205→
   206→**When to use:** For VIZ-04 requirement - show memory state during animation
   207→
   208→**Example:**
   209→```javascript
   210→// Pattern: Table-based memory viewer with hex formatting
   211→// Source: Debugger memory windows, ImHex patterns
   212→// https://docs.werwolv.net/imhex/views/pattern-data
   213→
   214→class MemoryView {
   215→  constructor(container) {
   216→    this.container = container;
   217→    this.container.className = 'memory-view';
   218→
   219→    // Track which addresses have changed for highlighting
   220→    this.previousMemory = new Map();
   221→
   222→    this._createTable();
   223→  }
   224→
   225→  _createTable() {
   226→    // Create table with fixed headers
   227→    this.container.innerHTML = `
   228→      <h3>Data Memory</h3>
   229→      <div class="memory-table-container">
   230→        <table class="memory-table">
   231→          <thead>
   232→            <tr>
   233→              <th>Address</th>
   234→              <th>Value</th>
   235→              <th>Decimal</th>
   236→            </tr>
   237→          </thead>
   238→          <tbody id="memory-tbody">
   239→            <!-- Rows created dynamically -->
   240→          </tbody>
   241→        </table>
   242→      </div>
   243→    `;
   244→
   245→    this.tbody = this.container.querySelector('#memory-tbody');
   246→  }
   247→
   248→  render(state) {
   249→    // Only show non-zero memory locations (typical for educational simulators)
   250→    const activeAddresses = [];
   251→    for (let i = 0; i < state.memory.length; i++) {
   252→      if (state.memory[i] !== 0) {
   253→        activeAddresses.push(i);
   254→      }
   255→    }
   256→
   257→    // Show message if no memory used yet
   258→    if (activeAddresses.length === 0) {
   259→      this.tbody.innerHTML = `
   260→        <tr class="empty-state">
   261→          <td colspan="3">No memory addresses in use</td>
   262→        </tr>
   263→      `;
   264→      return;
   265→    }
   266→
   267→    // Render rows for active addresses
   268→    this.tbody.innerHTML = activeAddresses.map(addr => {
   269→      const value = state.memory[addr];
   270→      const hexAddr = '0x' + (addr * 4).toString(16).padStart(8, '0').toUpperCase();
   271→      const hexValue = '0x' + value.toString(16).padStart(8, '0').toUpperCase();
   272→      const decValue = value;
   273→
   274→      // Check if this address changed this cycle
   275→      const changed = state.changedMemory.has(addr);
   276→      const rowClass = changed ? 'memory-row changed' : 'memory-row';
   277→
   278→      return `
   279→        <tr class="${rowClass}" data-address="${addr}">
   280→          <td class="memory-address">${hexAddr}</td>
   281→          <td class="memory-value">${hexValue}</td>
   282→          <td class="memory-decimal">${decValue}</td>
   283→        </tr>
   284→      `;
   285→    }).join('');
   286→  }
   287→}
   288→```
   289→
   290→**Why this pattern:**
   291→- Standard debugger memory window layout (address | hex | decimal)
   292→- Show only non-zero addresses (educational clarity)
   293→- Highlight changed addresses similar to RegisterView
   294→- Byte addresses (addr * 4) not word addresses for RISC authenticity
   295→
   296→### Pattern 3: Instruction View Component (Field Breakdown Display)
   297→
   298→**What:** View component showing current instruction with decoded fields (opcode, rs, rt, rd, immediate)
   299→
   300→**When to use:** For VIZ-05 requirement - show instruction field breakdown during execution
   301→
   302→**Example:**
   303→```javascript
   304→// Pattern: Instruction field breakdown display
   305→// Source: RISC-V instruction format visualizations
   306→// https://fraserinnovations.com/risc-v/risc-v-instruction-set-explanation/
   307→
   308→class InstructionView {
   309→  constructor(container) {
   310→    this.container = container;
   311→    this.container.className = 'instruction-view';
   312→
   313→    this._createLayout();
   314→  }
   315→
   316→  _createLayout() {
   317→    this.container.innerHTML = `
   318→      <h3>Current Instruction</h3>
   319→      <div class="instruction-display">
   320→        <div class="instruction-mnemonic" id="inst-mnemonic">
   321→          <span class="label">Instruction:</span>
   322→          <span class="value">—</span>
   323→        </div>
   324→        <div class="instruction-fields" id="inst-fields">
   325→          <!-- Fields populated dynamically -->
   326→        </div>
   327→        <div class="instruction-comment" id="inst-comment">
   328→          <!-- Comment populated dynamically -->
   329→        </div>
   330→      </div>
   331→    `;
   332→  }
   333→
   334→  render(state) {
   335→    // Determine which stage to show (prioritize later stages)
   336→    let currentInstruction = null;
   337→    let stageName = null;
   338→
   339→    // Check stages in reverse order (WB -> MEM -> EX -> ID -> IF)
   340→    if (state.pipeline.WB.active && state.pipeline.IF.instruction) {
   341→      currentInstruction = state.pipeline.IF.instruction;
   342→      stageName = 'WB';
   343→    } else if (state.pipeline.MEM.active && state.pipeline.IF.instruction) {
   344→      currentInstruction = state.pipeline.IF.instruction;
   345→      stageName = 'MEM';
   346→    } else if (state.pipeline.EX.active && state.pipeline.IF.instruction) {
   347→      currentInstruction = state.pipeline.IF.instruction;
   348→      stageName = 'EX';
   349→    } else if (state.pipeline.ID.active && state.pipeline.IF.instruction) {
   350→      currentInstruction = state.pipeline.IF.instruction;
   351→      stageName = 'ID';
   352→    } else if (state.pipeline.IF.active && state.pipeline.IF.instruction) {
   353→      currentInstruction = state.pipeline.IF.instruction;
   354→      stageName = 'IF';
   355→    }
   356→
   357→    // No instruction active
   358→    if (!currentInstruction) {
   359→      this.container.querySelector('#inst-mnemonic .value').textContent = 'No instruction active';
   360→      this.container.querySelector('#inst-fields').innerHTML = '';
   361→      this.container.querySelector('#inst-comment').textContent = '';
   362→      return;
   363→    }
   364→
   365→    // Get instruction definition
   366→    const instDef = InstructionSet.get(currentInstruction.mnemonic);
   367→
   368→    // Display mnemonic
   369→    const mnemonicEl = this.container.querySelector('#inst-mnemonic .value');
   370→    mnemonicEl.textContent = `${currentInstruction.mnemonic} (${stageName} stage)`;
   371→
   372→    // Display fields based on instruction type
   373→    const fieldsEl = this.container.querySelector('#inst-fields');
   374→    fieldsEl.innerHTML = this._formatFields(currentInstruction, instDef);
   375→
   376→    // Display comment if available
   377→    const commentEl = this.container.querySelector('#inst-comment');
   378→    commentEl.textContent = currentInstruction.comment || '';
   379→  }
   380→
   381→  _formatFields(instruction, definition) {
   382→    const fields = [];
   383→
   384→    // Opcode (always present)
   385→    fields.push(`<div class="field">
   386→      <span class="field-name">Opcode:</span>
   387→      <span class="field-value">${instruction.mnemonic}</span>
   388→    </div>`);
   389→
   390→    // rs (source register 1)
   391→    if (definition.fields.rs) {
   392→      fields.push(`<div class="field">
   393→        <span class="field-name">rs:</span>
   394→        <span class="field-value">$${instruction.rs}</span>
   395→      </div>`);
   396→    }
   397→
   398→    // rt (source register 2 or target for I-type)
   399→    if (definition.fields.rt) {
   400→      fields.push(`<div class="field">
   401→        <span class="field-name">rt:</span>
   402→        <span class="field-value">$${instruction.rt}</span>
   403→      </div>`);
   404→    }
   405→
   406→    // rd (destination register for R-type)
   407→    if (definition.fields.rd) {
   408→      fields.push(`<div class="field">
   409→        <span class="field-name">rd:</span>
   410→        <span class="field-value">$${instruction.rd}</span>
   411→      </div>`);
   412→    }
   413→
   414→    // Immediate value
   415→    if (definition.fields.immediate) {
   416→      const immValue = instruction.immediate;
   417→      const immHex = immValue >= 0
   418→        ? '0x' + immValue.toString(16).toUpperCase()
   419→        : '-0x' + Math.abs(immValue).toString(16).toUpperCase();
   420→
   421→      fields.push(`<div class="field">
   422→        <span class="field-name">Immediate:</span>
   423→        <span class="field-value">${immValue} (${immHex})</span>
   424→      </div>`);
   425→    }
   426→
   427→    return fields.join('');
   428→  }
   429→}
   430→```
   431→
   432→**Why this pattern:**
   433→- Shows currently executing instruction (not all instructions)
   434→- Breaks down fields according to instruction type (R, I, S, B, J)
   435→- Displays immediate values in both decimal and hex
   436→- Shows which stage is executing the instruction (educational clarity)
   437→
   438→### Pattern 4: Clickable Instruction List (Jump-to-Frame)
   439→
   440→**What:** Scrollable list of program instructions with click-to-jump functionality
   441→
   442→**When to use:** For DEMO-05 requirement - allow jumping to specific instruction in animation
   443→
   444→**Example:**
   445→```javascript
   446→// Pattern: Clickable instruction list with current-instruction highlighting
   447→// Source: CPUlator, WepSIM simulator patterns
   448→// https://cpulator.01xz.net/
   449→
   450→class InstructionList {
   451→  constructor(container, engine) {
   452→    this.container = container;
   453→    this.engine = engine;
   454→    this.instructions = [];
   455→    this.instructionToFrameMap = new Map(); // instruction index -> first IF frame
   456→
   457→    this._createLayout();
   458→
   459→    // Listen to frame changes to update current instruction
   460→    window.addEventListener('cpu:framechange', () => this._updateCurrentInstruction());
   461→  }
   462→
   463→  _createLayout() {
   464→    this.container.innerHTML = `
   465→      <h3>Program Instructions</h3>
   466→      <div class="instruction-list-container">
   467→        <ol class="instruction-list" id="inst-list">
   468→          <!-- Instructions populated on load -->
   469→        </ol>
   470→      </div>
   471→    `;
   472→
   473→    this.listElement = this.container.querySelector('#inst-list');
   474→  }
   475→
   476→  loadProgram(program, frameSequence) {
   477→    this.instructions = program.instructions;
   478→
   479→    // Build map from instruction index to frame index
   480→    // Each instruction has 5 frames (IF, ID, EX, MEM, WB)
   481→    // Frame 0 is initial state, then instruction 0 starts at frame 1
   482→    this.instructionToFrameMap.clear();
   483→
   484→    frameSequence.frames.forEach((frame, frameIndex) => {
   485→      if (frame.pipeline.IF.active && frame.pipeline.IF.instruction) {
   486→        const pc = frame.pipeline.IF.pc;
   487→        const instructionIndex = pc / 4;
   488→
   489→        // Store only the first IF frame for each instruction
   490→        if (!this.instructionToFrameMap.has(instructionIndex)) {
   491→          this.instructionToFrameMap.set(instructionIndex, frameIndex);
   492→        }
   493→      }
   494→    });
   495→
   496→    // Render instruction list
   497→    this.listElement.innerHTML = this.instructions.map((inst, index) => {
   498→      const frameIndex = this.instructionToFrameMap.get(index);
   499→      const canJump = frameIndex !== undefined;
   500→
   501→      return `
   502→        <li class="instruction-item"
   503→            data-index="${index}"
   504→            data-frame="${frameIndex || 0}"
   505→            ${canJump ? 'tabindex="0"' : ''}>
   506→          <span class="inst-mnemonic">${inst.mnemonic}</span>
   507→          ${this._formatOperands(inst)}
   508→          ${inst.comment ? `<span class="inst-comment">// ${inst.comment}</span>` : ''}
   509→        </li>
   510→      `;
   511→    }).join('');
   512→
   513→    // Wire up click handlers
   514→    this.listElement.querySelectorAll('.instruction-item[tabindex]').forEach(item => {
   515→      item.addEventListener('click', () => {
   516→        const frameIndex = parseInt(item.dataset.frame);
   517→        this.engine.jumpToFrame(frameIndex);
   518→      });
   519→
   520→      // Keyboard accessibility
   521→      item.addEventListener('keydown', (e) => {
   522→        if (e.code === 'Enter' || e.code === 'Space') {
   523→          e.preventDefault();
   524→          const frameIndex = parseInt(item.dataset.frame);
   525→          this.engine.jumpToFrame(frameIndex);
   526→        }
   527→      });
   528→    });
   529→  }
   530→
   531→  _formatOperands(instruction) {
   532→    const parts = [];
   533→
   534→    if (instruction.rd !== undefined) parts.push(`$${instruction.rd}`);
   535→    if (instruction.rs !== undefined) parts.push(`$${instruction.rs}`);
   536→    if (instruction.rt !== undefined) parts.push(`$${instruction.rt}`);
   537→    if (instruction.immediate !== undefined) parts.push(instruction.immediate);
   538→
   539→    return parts.length > 0
   540→      ? `<span class="inst-operands">${parts.join(', ')}</span>`
   541→      : '';
   542→  }
   543→
   544→  _updateCurrentInstruction() {
   545→    const currentFrame = this.engine.getCurrentFrameIndex();
   546→    const currentState = this.engine.getCurrentState();
   547→
   548→    if (!currentState) return;
   549→
   550→    // Find which instruction is currently in IF stage
   551→    let currentPC = null;
   552→    if (currentState.pipeline.IF.active) {
   553→      currentPC = currentState.pipeline.IF.pc;
   554→    }
   555→
   556→    // Update highlighting
   557→    this.listElement.querySelectorAll('.instruction-item').forEach(item => {
   558→      const index = parseInt(item.dataset.index);
   559→      const isActive = currentPC !== null && (currentPC / 4) === index;
   560→
   561→      if (isActive) {
   562→        item.classList.add('active');
   563→      } else {
   564→        item.classList.remove('active');
   565→      }
   566→    });
   567→  }
   568→}
   569→```
   570→
   571→**Why this pattern:**
   572→- Ordered list (`<ol>`) shows instruction sequence clearly
   573→- Click or keyboard (Enter/Space) to jump to instruction
   574→- Current instruction highlighted as animation plays
   575→- Frame mapping handles multi-stage execution (each instruction = 5 frames)
