   816→### Hex Address/Value Formatting
   817→```javascript
   818→// Source: MDN - Number.prototype.toString()
   819→// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number/toString
   820→
   821→function formatHex32(value) {
   822→  // Convert to 32-bit unsigned, then to hex with 8 digits
   823→  return '0x' + (value >>> 0).toString(16).padStart(8, '0').toUpperCase();
   824→}
   825→
   826→function formatAddress(wordIndex) {
   827→  // Byte addresses (word index * 4)
   828→  const byteAddress = wordIndex * 4;
   829→  return '0x' + byteAddress.toString(16).padStart(8, '0').toUpperCase();
   830→}
   831→
   832→// Usage
   833→formatHex32(255);          // "0x000000FF"
   834→formatHex32(-1);           // "0xFFFFFFFF" (two's complement)
   835→formatAddress(10);         // "0x00000028" (byte address for word 10)
   836→```
