   894→### Program Loading with Error Handling
   895→```javascript
   896→// Source: Error handling best practices
   897→// https://javascript.info/try-catch
   898→
   899→class ProgramSelector {
   900→  _loadProgram(programKey) {
   901→    try {
   902→      const program = this.programs[programKey];
   903→
   904→      if (!program) {
   905→        throw new Error(`Program '${programKey}' not found`);
   906→      }
   907→
   908→      if (!program.instructions || program.instructions.length === 0) {
   909→        throw new Error(`Program '${programKey}' has no instructions`);
   910→      }
   911→
   912→      // Generate frame sequence
   913→      const result = SequenceGenerator.generateSequence(program.instructions);
   914→
   915→      if (!result.frames || result.frames.length === 0) {
   916→        throw new Error(`Failed to generate frames for '${programKey}'`);
   917→      }
   918→
   919→      // Load frames into animation engine
   920→      this.engine.loadFrames(result.frames);
   921→
   922→      // Update instruction list
   923→      if (this.instructionList) {
   924→        this.instructionList.loadProgram(program, result);
   925→      }
   926→
   927→      console.log(`Loaded program: ${program.name} (${result.frames.length} frames)`);
   928→
   929→    } catch (error) {
   930→      console.error('Failed to load program:', error);
   931→
   932→      // Show user-friendly error message
   933→      this.container.querySelector('#error-message').textContent =
   934→        `Error: Could not load program '${programKey}'. ${error.message}`;
